    @EventHandler( payloadType=UpdateAnomalyEvent.class )
    public void handle( UpdateAnomalyEvent event) {
    	LOGGER.info("handling UpdateAnomalyEvent - " + event );
    	
	    Anomaly entity = new Anomaly();
            entity.setAnomalyId( event.getAnomalyId() );
            entity.setOccurredAt( event.getOccurredAt() );
            entity.setDetails( event.getDetails() );
            entity.setTimeSeries( event.getTimeSeries() );
            entity.setAlert( event.getAlert() );
            entity.setDataset( event.getDataset() );
            entity.setAnomalyType( event.getAnomalyType() );
            entity.setSeverity( event.getSeverity() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindAnomaly( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAnomaly( entity );        
    }
    
