    /**
     * Method to retrieve the Anomaly via an AnomalyPrimaryKey.
     * @param 	id Long
     * @return 	Anomaly
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Anomaly handle( FindAnomalyQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAnomalyId() );
    }
    
    /**
     * Method to retrieve a collection of all Anomalys
     *
     * @param	query	FindAllAnomalyQuery 
     * @return 	List<Anomaly> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Anomaly> handle( FindAllAnomalyQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAnomaly,
 * but only if the id matches
 *
 * @param		entity	Anomaly
 */
	protected void emitFindAnomaly( Anomaly entity ) {
		LOGGER.info("handling emitFindAnomaly" );
		
	    queryUpdateEmitter.emit(FindAnomalyQuery.class,
	                            query -> query.getFilter().getAnomalyId().equals(entity.getAnomalyId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAnomaly
	 * 
	 * @param		entity	Anomaly
	 */
	protected void emitFindAllAnomaly( Anomaly entity ) {
		LOGGER.info("handling emitFindAllAnomaly" );
		
	    queryUpdateEmitter.emit(FindAllAnomalyQuery.class,
	                            query -> true,
	                            entity);
	}

